fn words_of(s: Str) -> List[Str] {
    var out: List[Str] = []
    var cur = ""
    for c in s.chars() {
        if c == " " {
            if cur != "" {
                out = out.push(cur)
                cur = ""
            }
        } else {
            cur = cur + c
        }
    }
    if cur != "" {
        out = out.push(cur)
    }
    return out
}

