    var env: Map[Str, Int] = {}
    for line in lines {
        let w = words_of(line)
        let n = w.len()
        if n < 3 or (n / 2) * 2 == n {
            return Err("syntax error")
        }
        let name = str_at(w, 0)
        if not is_name(name) or str_at(w, 1) != "=" {
            return Err("syntax error")
        }

        var p = 2
        while p < n {
            let t = str_at(w, p)
            let k = p - 2
            if (k / 2) * 2 == k {
                if not (is_int(t) or is_name(t)) {
                    return Err("syntax error")
                }
            } else {
                if t != "+" and t != "-" {
                    return Err("syntax error")
                }
            }
            p = p + 1
        }

        var acc = 0
        var op = "+"
        p = 2
        while p < n {
            let t = str_at(w, p)
            let k = p - 2
            if (k / 2) * 2 == k {
                var v = 0
                if is_int(t) {
                    v = num_of(t)
                } else {
                    match env.get(t) {
                        Some(x) => {
                            v = x
                        }
                        None => {
                            return Err("undefined " + t)
                        }
                    }
                }
                if op == "+" {
                    acc = acc + v
                } else {
                    acc = acc - v
                }
            } else {
                op = t
            }
            p = p + 1
        }
        env = env.set(name, acc)
    }
    return Ok(env)
}

